const body = $input.item.json.body || {};
function escapeHtml(unsafe) {
    if (!unsafe) return '';
    return String(unsafe).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}

let lead = {
  landing_id: escapeHtml(body.landing_id),
  nome: escapeHtml(body.nome),
  telefone: escapeHtml(body.telefone),
  email: escapeHtml(body.email),
  data_preferida: escapeHtml(body.data_preferida),
  mensagem: escapeHtml(body.mensagem),
  timestamp: new Date().toISOString()
};

if (!lead.landing_id || !lead.nome || !lead.telefone || !lead.email) {
  throw new Error("Campos obrigatorios em falta.");
}

let phone = lead.telefone.replace(/[^0-9+]/g, '');
if (!phone.startsWith('+')) {
  if (phone.length === 9) phone = '+351' + phone;
  else phone = '+' + phone;
}
lead.telefone = phone;

return {
  json: {
    lead: lead,
    stateFilePath: '/home/node/.n8n-files/builds/' + lead.landing_id + '.state.json'
  }
};

const lead = $('Pre-processa Lead').item.json.lead;
const statePath = $('Pre-processa Lead').item.json.stateFilePath;
let stateStr = '';

if ($input.item.binary && ($input.item.binary.stateData || $input.item.binary.data)) {
  const propName = $input.item.binary.stateData ? 'stateData' : 'data';
  const buffer = await this.helpers.getBinaryDataBuffer(0, propName);
  stateStr = buffer.toString('utf8');
} else {
  throw new Error("State data nao encontrado");
}

let state = JSON.parse(stateStr);
if (!state.leads) state.leads = [];
state.leads.push(lead);

let corretor = (state.imovel && state.imovel.corretor) || (state.cliente && state.cliente.corretor) || {};
let targetEmail = (corretor.email && corretor.email.trim()) ? corretor.email.trim() : 'ibissonsilva@gmail.com';
let titulo = (state.imovel && state.imovel.titulo) || "Imovel sem titulo";

const updatedStateStr = JSON.stringify(state, null, 2);
const stateBuffer = Buffer.from(updatedStateStr, 'utf8');
const stateBase64 = stateBuffer.toString('base64');

$input.item.binary = $input.item.binary || {};
$input.item.binary.updatedState = {
  data: stateBase64,
  mimeType: 'application/json',
  fileName: lead.landing_id + '.state.json'
};

return {
  json: {
    lead: lead,
    corretor: corretor,
    targetEmail: targetEmail,
    titulo: titulo,
    stateFilePath: statePath
  },
  binary: $input.item.binary
};
